import{z as n,x as r,o as E,c,q as o,j as s,D as e,d as i,s as d,S as l}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"静态对动态链接","description":"","frontmatter":{"title":"静态对动态链接","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/static-vs-dynamic-link.md","filePath":"cs/static-vs-dynamic-link.md","lastUpdated":1791413859000}'),A={name:"cs/static-vs-dynamic-link.md"};function B(p,a,T,_,D,m){const t=r("Mermaid");return E(),c("div",null,[a[2]||(a[2]=o('<h1 id="静态对动态链接" tabindex="-1">静态对动态链接 <a class="header-anchor" href="#静态对动态链接" aria-label="Permalink to &quot;静态对动态链接&quot;">​</a></h1><div class="epigraph"><p>静态把库目标编进可执行文件；动态把依赖推迟到加载，符号经 GOT/PLT 绑定。二者对体积、更新与启动时间的答案相反。</p><footer>—— 据 Levine；主干[GOT 与 PLT](/cs/got-plt)、[加载与动态链接](/cs/load-dynlink)；System V ABI 整理</footer></div><p>上一课<a href="/cs/linker-script-sections">链接脚本</a> 排段。缺口是<strong>库怎么交付</strong>：<code>.a</code> 抽进文本 vs <code>.so</code> 运行时映射。主干已有 GOT/PLT。本课钉权衡与符号绑定时机（立即/延迟），插入下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态：闭世界，LTO 狠，无启动解析，体积大、安全更新要重链。动态：共享内存页、可替换 <code>.so</code>，启动走加载器，ABI 必须稳。缺口是<strong>选择合同</strong>，不是脚本语法。</p><p>PIE：可执行也位置无关，ASLR。静态 PIE 存在，但是另一打包。</p><p><span class="marginnote">常见误区：初学者容易以为动态链接的程序「编译完就能跑、和链接无关」。实际上它编译时就已写下符号引用与 <code>DT_NEEDED</code> 列表，启动时加载器还要按重定位表把地址补上——链接没有消失，只是从构建机器搬到了运行机器上。</span></p><h3 id="动态不是「不链接」" tabindex="-1">动态不是「不链接」 <a class="header-anchor" href="#动态不是「不链接」" aria-label="Permalink to &quot;动态不是「不链接」&quot;">​</a></h3><p>仍有链接：产生 <code>DT_NEEDED</code> 与重定位。只是把最终地址推迟。不要说动态程序「没被链接」。</p><p><span class="marginnote">Levine。SysV。主干 got-plt、load-dynlink。本课对照表，不重画 PLT 桩。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>gcc -static</code> vs 默认动态。查看：<code>ldd</code>、<code>readelf -d</code>。静态 libc 的法律与兼容（glibc 不鼓励完全静态）是工程现实。musl 更常静态。</p>',12)),(E(),s(l,null,{default:e(()=>[d(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22.o%22%5D%20--%3E%20ST%5B%22%E9%9D%99%E6%80%81%EF%BC%9A%E6%94%B6%E8%BF%9B%E5%8F%AF%E6%89%A7%E8%A1%8C%22%5D%0A%20%20SRC%20--%3E%20DY%5B%22%E5%8A%A8%E6%80%81%EF%BC%9ADT_NEEDED%22%5D%0A%20%20DY%20--%3E%20LDSO%5B%22%E5%8A%A0%E8%BD%BD%E5%99%A8%E7%BB%91%E5%AE%9A%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<p>与可见性：动态导出过多则慢且易冲突。<code>--exclude-libs</code> 等。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>版本：<code>GLIBC_2.xx</code> 符号版本。静态无此运行时绑定，但内核 syscall 仍在。不要把静态当「无未定义行为」。</p><p>插件：<code>dlopen</code> 只在动态世界自然；静态要自注册表。</p><p>同一次「printf」调用，在两种交付方式下走到的路径完全不同，绑定时机的差别全部体现在这条路径上。</p>',5)),(E(),s(l,null,{default:e(()=>[d(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20CALL%5B%22%E7%A8%8B%E5%BA%8F%E8%B0%83%E7%94%A8%20printf%22%5D%20--%3E%20STP%5B%22%E9%9D%99%E6%80%81%3A%20%E9%93%BE%E6%8E%A5%E6%9C%9F%E5%B7%B2%E6%8A%8A%20printf%20%E6%9C%BA%E5%99%A8%E7%A0%81%E6%94%B6%E8%BF%9B%E5%8F%AF%E6%89%A7%E8%A1%8C%22%5D%0A%20%20STP%20--%3E%20STJ%5B%22%E8%BF%90%E8%A1%8C%E6%97%B6%E7%9B%B4%E6%8E%A5%E8%B7%B3%E6%9C%AC%E6%96%87%E4%BB%B6%E5%86%85%E5%9C%B0%E5%9D%80%22%5D%0A%20%20CALL%20--%3E%20PLT%5B%22%E5%8A%A8%E6%80%81%3A%20%E5%85%88%E8%BF%9B%20PLT%20%E6%A1%A9%22%5D%0A%20%20PLT%20--%3E%20GOT%5B%22%E6%9F%A5%20GOT%20%E6%98%AF%E5%90%A6%E5%B7%B2%E8%A7%A3%E6%9E%90%22%5D%0A%20%20GOT%20--%20%22%E6%9C%AA%E8%A7%A3%E6%9E%90%22%20--%3E%20LDSO%5B%22%E5%8A%A0%E8%BD%BD%E5%99%A8%2Fdyld%20%E6%89%BE%20.so%20%E5%A1%AB%20GOT%22%5D%0A%20%20GOT%20--%20%22%E5%B7%B2%E8%A7%A3%E6%9E%90%22%20--%3E%20JUMP%5B%22%E7%9B%B4%E6%8E%A5%E8%B7%B3%20printf%20%E5%AE%9E%E9%99%85%E5%9C%B0%E5%9D%80%22%5D%0A%20%20LDSO%20--%3E%20JUMP%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=o('<p><span class="marginnote">数字实例：一个只调用 libc 十几个函数的 C 程序，静态链接后通常在 800 KB 到 1 MB 量级；同一程序动态链接可能只有十几 KB——但前提是目标机器上恰好装着版本兼容的 libc，这正是「体积换依赖」的合同。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 <code>LD_PRELOAD</code> 全文。后课默认：动态靠 GOT/PLT 与加载器。下一课符号插入与 <code>LD_PRELOAD</code>。</p><p>也不把动态链接当解释器字节码。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>静态：闭世界、体积、更新难。</li><li>动态：共享与可替换，推迟绑定。</li><li>仍有链接，只是分阶段。</li><li>出处：Levine；System V ABI；对照主干 GOT/PLT。</li></ul>',6))])}const f=n(A,[["render",B]]);export{P as __pageData,f as default};
